"""Three bugs found while testing the Arabic build on a real phone.

1. Changing the language left the bottom navigation bar, the Report button and
   the screen you were on in the previous language until you navigated away and
   came back. t() reads the language from a plain singleton, so nothing in the
   widget tree depended on it and nothing rebuilt by itself; a route's content
   is also built once and then cached, so rebuilding MaterialApp never reached
   inside it. Fixed with a SettingsListener that the shell and the settings
   screen both use.

2. The AI summary on the report screen always came back in French, whatever the
   app language, because the triage prompt hardcoded "resume factuel en
   francais" and the app never sent its language to that endpoint at all.

3. An Arabic street name inside a French or English sentence dragged the
   surrounding words around it, so the route card rendered "Via :" at the end of
   its own line. Fixed by isolating each name with U+2068 / U+2069.

Run it from the root of the repository:

    py fix_language_bugs.py

Safe to run twice. It changes the backend as well as the app, so the backend
container has to be rebuilt afterwards.
"""

import base64
import pathlib
import sys

FILES = {
    'backend/app/ai/assistant.py':
        '',
    'backend/app/api/assistant.py':
        '',
    'backend/app/schemas.py':
        '',
    'backend/tests/test_triage_guard.py':
        '',
    'mobile/lib/api.dart':
        '',
    'mobile/lib/i18n.dart':
        '',
    'mobile/lib/main.dart':
        '',
    'mobile/lib/models.dart':
        '',
    'mobile/lib/screens/assistant_screen.dart':
        '',
    'mobile/lib/screens/dashboard_screen.dart':
        '',
    'mobile/lib/screens/map_screen.dart':
        '',
    'mobile/lib/screens/pick_location.dart':
        '',
    'mobile/lib/screens/report_screen.dart':
        '',
    'mobile/lib/screens/settings_screen.dart':
        '',
    'mobile/lib/settings.dart':
        '',
    'mobile/test/models_test.dart':
        '',
}


def main() -> int:
    root = pathlib.Path.cwd()
    if not (root / "mobile" / "lib" / "main.dart").is_file():
        print("Run this from the repository root (the folder that contains 'mobile').")
        print("You are in:", root)
        return 1
    for name, blob in FILES.items():
        path = root / name
        data = base64.b64decode(blob)
        before = path.read_bytes() if path.is_file() else b""
        path.write_bytes(data)
        print(("unchanged  " if before == data else "written    ") + name)
    print()
    print("Backend (the prompt changed, so it has to be rebuilt):")
    print("    docker compose up -d --build backend")
    print("    docker compose exec backend python -m pytest tests -q")
    print()
    print("App:")
    print("    cd mobile")
    print("    flutter analyze --no-fatal-infos")
    print("    flutter test")
    return 0


if __name__ == "__main__":
    sys.exit(main())
